#include <iostream>
#include <array>
#include <string>

void inspect_static_array() {
    // Static local array: initialized once at startup to zero
    static int call_counts[3]{};
    call_counts[0]++;
    std::cout << "Static call_counts[0]: " << call_counts[0] << "\n";
}

int main() {
    // Modern C++17 std::array with zero-initialization
    constexpr std::size_t SIZE = 5;
    std::array<int, SIZE> numbers{10, 20}; // remaining elements become 0

    std::cout << "Elements in numbers:";
    for (std::size_t i = 0; i < numbers.size(); ++i) {
        std::cout << " " << numbers[i];
    }
    std::cout << "\n";

    // Secure output: avoid user-controlled format string
    std::string user_greeting = "Hello, Secure C++!";
    std::cout << user_greeting << "\n";

    // Static local persistence across calls
    inspect_static_array();
    inspect_static_array();

    // Safe bounds check
    try {
        numbers.at(2) = 30;
        std::cout << "numbers.at(2) = " << numbers.at(2) << "\n";
        // numbers.at(10) = 99; // Would throw std::out_of_range
    } catch (const std::out_of_range& e) {
        std::cout << "Caught bounds error: " << e.what() << "\n";
    }

    return 0;
}

#include <iostream>
#include <array>

// Bubble sort implementation using C++17 std::array reference
template <std::size_t N>
void bubble_sort(std::array<int, N>& arr) {
    for (std::size_t pass = 0; pass < arr.size() - 1; ++pass) {
        for (std::size_t i = 0; i < arr.size() - 1 - pass; ++i) {
            if (arr[i] > arr[i + 1]) {
                int temp = arr[i];
                arr[i] = arr[i + 1];
                arr[i + 1] = temp;
            }
        }
    }
}

// Binary search implementation
template <std::size_t N>
int binary_search(const std::array<int, N>& arr, int key) {
    int low = 0;
    int high = static_cast<int>(arr.size()) - 1;

    while (low <= high) {
        int mid = low + (high - low) / 2;
        if (arr[mid] == key) {
            return mid;
        }
        if (arr[mid] < key) {
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }
    return -1; // Not found
}

int main() {
    std::array<int, 6> data{34, 12, 89, 5, 23, 77};

    bubble_sort(data);

    std::cout << "Sorted array:";
    for (int val : data) {
        std::cout << " " << val;
    }
    std::cout << "\n";

    int key = 23;
    int index = binary_search(data, key);
    if (index != -1) {
        std::cout << "Key " << key << " found at index " << index << "\n";
    } else {
        std::cout << "Key " << key << " not found\n";
    }

    return 0;
}

#include <iostream>
#include <vector>

// Parameter declaration requires the column size (3)
void print_table(const int table[][3], int rows) {
    for (int r = 0; r < rows; ++r) {
        for (int c = 0; c < 3; ++c) {
            std::cout << table[r][c] << " ";
        }
        std::cout << "\n";
    }
}

int main() {
    constexpr int ROWS = 2;
    constexpr int COLS = 3;

    // 2D array with partial row initializers (unspecified elements become 0)
    int table[ROWS][COLS] = {
        {1, 2},    // table[0][2] becomes 0
        {4, 5, 6}
    };

    std::cout << "Fixed 2D array content:\n";
    print_table(table, ROWS);

    // Modern C++ dynamic alternative to C99 VLA
    int dynamic_rows = 2;
    int dynamic_cols = 3;
    std::vector<std::vector<int>> safe_matrix(
        dynamic_rows, std::vector<int>(dynamic_cols, 0)
    );

    for (int r = 0; r < dynamic_rows; ++r) {
        for (int c = 0; c < dynamic_cols; ++c) {
            safe_matrix[r][c] = (r + 1) * 10 + (c + 1);
        }
    }

    std::cout << "Dynamic std::vector 2D grid:\n";
    for (const auto& row : safe_matrix) {
        for (int val : row) {
            std::cout << val << " ";
        }
        std::cout << "\n";
    }

    return 0;
}
